{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "body",
      "type": "ReactNode",
      "description": "Primary message content.",
      "required": true,
      "slotElements": [
        {
          "__element": "Text",
          "props": {
            "type": "body"
          },
          "children": "Toast message"
        }
      ]
    },
    {
      "name": "type",
      "type": "'info' | 'error'",
      "description": "Toast type controlling background color. Error toasts persist until dismissed.",
      "default": "'info'"
    },
    {
      "name": "isAutoHide",
      "type": "boolean",
      "description": "Whether the toast auto-dismisses. Defaults to true for info, false for error."
    },
    {
      "name": "autoHideDuration",
      "type": "number",
      "description": "Duration in ms before auto-dismiss. Timed content must satisfy WCAG 2.2.1.",
      "default": "5000"
    },
    {
      "name": "endContent",
      "type": "ReactNode",
      "description": "Content rendered at the trailing end (e.g. Undo button, link). Keep action labels short.",
      "slotElements": [
        {
          "__element": "Icon",
          "props": {
            "icon": "chevronDown",
            "size": "sm"
          }
        },
        {
          "__element": "Badge",
          "props": {
            "label": "3"
          }
        }
      ]
    },
    {
      "name": "uniqueID",
      "type": "string",
      "description": "Unique identifier for deduplication."
    },
    {
      "name": "collisionBehavior",
      "type": "'overwrite' | 'ignore'",
      "description": "Behavior when a toast with matching uniqueID already exists.",
      "default": "'overwrite'"
    },
    {
      "name": "onHide",
      "type": "(reason: \"auto\" | \"manual\") => void",
      "description": "Callback fired when the toast is removed."
    },
    {
      "name": "onDismiss",
      "type": "(reason: \"auto\" | \"manual\") => void",
      "description": "Callback fired when the toast is dismissed.",
      "required": true
    },
    {
      "name": "renderContent",
      "type": "(toast: ToastContentRenderProps) => ReactNode",
      "description": "Replaces the content of this toast's card with your own layout. Astryx keeps the card, its astryx-toast theme target and auto-hide behavior (inside a ToastViewport the viewport announces the toast, over a modal too, and the card itself is not a live region), then hands the renderer the message, endContent, resolved toast settings and a dismiss callback. The custom renderer owns every control in its layout: compose the control you want and call dismiss from it. Astryx does not inject a fallback close into custom content. Per-toast: an app shares one layout by wrapping useToast and passing it on every call, while a toast raised by library code that never passes it renders as an ordinary Astryx toast. The argument is {body, endContent, type, isAutoHide, autoHideDuration, dismiss}, where type is 'info' | 'error'."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
